INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('42ca9524-49e4-5fa4-ae5e-5452b61bb0e0','TEXT','The Tiny Ferry — A Different Day','When Priya first became interested in the model ferry, the task at the river workshop looked routine. Yet on Wednesday, an unexpected problem appeared. A hurried solution would have been possible, but Priya suspected that the first explanation was too simple. Instead, Priya treated the problem as a small investigation.
